ssh rowan-dev 'mkdir -p /tmp/chr && cp ~/.config/chromium/Default/{History,Cookies,Preferences} /tmp/chr/ && cd /tmp/chr && cat Preferences; echo; echo "=== urls"; sqlite3 History "select id,url,title,visit_count,last_visit_time from urls order by last_visit_time desc;" 2>&1 | head -60; echo "=== downloads"; sqlite3 History "select id,current_path,target_path,tab_url,tab_referrer_url,mime_type,total_bytes,state,danger_type from downloads;" 2>&1 | head -20; echo "=== chains"; sqlite3 History "select * from downloads_url_chains;" 2>&1 | head -20; echo "=== cookies"; sqlite3 Cookies ".schema cookies" 2>&1 | head -5; sqlite3 Cookies "select host_key,name,path,length(encrypted_value),expires_utc,is_secure,is_httponly from cookies;" 2>&1 | head -40; echo "=== keywords"; sqlite3 History "select * from keyword_search_terms;" 2>&1 | head -20'
